it('persists a view switch without changing the global durable snapshot', async () => {
    vi.useFakeTimers()
    vi.resetModules()
    const { Store } = await import('./persistence')
    const dataFile = join(testState.dir, 'orca-data.json')
    const store = createSqliteTestStore(Store, { dataFile })
    store.flush()
    const durableBefore = readPersistedStateJson(dataFile)

    store.updateUI({ activeView: 'settings' })
    vi.advanceTimersByTime(1_000)
    await store.waitForPendingWrite()

    const preferenceFile = getActiveViewPreferenceFile(dataFile)
    const preferencePayload = readFileSync(preferenceFile, 'utf-8')
    expect(Buffer.byteLength(preferencePayload)).toBeLessThan(64)
    expect(JSON.parse(preferencePayload)).toEqual({ activeView: 'settings' })
    expect(readPersistedStateJson(dataFile)).toBe(durableBefore)
    expect(store.getUI().activeView).toBe('settings')

    const reloaded = createSqliteTestStore(Store, { dataFile })
    expect(reloaded.getUI().activeView).toBe('settings')
  })

it('a write parked on its rename cannot overwrite a later flushOrThrow', async () => {
    const { ActiveViewPreference } = await import('./active-view-preference')
    const pref = new ActiveViewPreference(join(dir, 'orca-data.json'), 'terminal')

    gate.blockRename = true
    pref.set('activity')
    await vi.waitFor(() => expect(gate.renameCalls).toBeGreaterThan(0))
    // Why grab it now: flushOrThrow drops pendingWrite, so waitForPendingWrite would
    // return before the released rename has actually landed.
    const inflight = (pref as unknown as { pendingWrite: Promise<void> | null }).pendingWrite

    // A session checkpoint fires while that write is still parked.
    pref.set('tasks')
    pref.flushOrThrow()
    expect(JSON.parse(readFileSync(viewFile(), 'utf-8')).activeView).toBe('tasks')

    gate.blockRename = false
    gate.waiters.splice(0).forEach((resolve) => resolve())
    await inflight

    expect(JSON.parse(readFileSync(viewFile(), 'utf-8')).activeView).toBe('tasks')
    expect(readdirSync(dir).filter((f) => f.endsWith('.tmp'))).toHaveLength(0)
  })

it('a completed stale rename cannot regress the persisted marker', async () => {
    const { ActiveViewPreference } = await import('./active-view-preference')
    const pref = new ActiveViewPreference(join(dir, 'orca-data.json'), 'terminal')
    const renameCompleted = new Promise<void>((resolve) => gate.renameCompleted.push(resolve))

    gate.blockAfterRename = true
    pref.set('activity')
    await renameCompleted

    pref.set('tasks')
    pref.flushOrThrow()
    gate.blockAfterRename = false
    gate.afterRenameWaiters.splice(0).forEach((resolve) => resolve())
    await pref.waitForPendingWrite()

    pref.set('activity')
    await vi.waitFor(() => {
      expect(JSON.parse(readFileSync(viewFile(), 'utf-8')).activeView).toBe('activity')
    })
    await pref.waitForPendingWrite()
  })

it('a pending flush drains a view changed during its rename', async () => {
    const { ActiveViewPreference } = await import('./active-view-preference')
    const pref = new ActiveViewPreference(join(dir, 'orca-data.json'), 'terminal')

    gate.blockRename = true
    pref.set('activity')
    const flush = pref.flushPendingAsync()
    await vi.waitFor(() => expect(gate.renameCalls).toBeGreaterThan(0))

    pref.set('tasks')
    gate.blockRename = false
    gate.waiters.splice(0).forEach((resolve) => resolve())
    await flush

    expect(JSON.parse(readFileSync(viewFile(), 'utf-8')).activeView).toBe('tasks')
    expect(gate.renameCalls).toBe(2)
  })

it('coalesces concurrent pending flushes while draining the newest view', async () => {
    const { ActiveViewPreference } = await import('./active-view-preference')
    const pref = new ActiveViewPreference(join(dir, 'orca-data.json'), 'terminal')

    gate.blockRename = true
    pref.set('activity')
    const firstFlush = pref.flushPendingAsync()
    await vi.waitFor(() => expect(gate.renameCalls).toBeGreaterThan(0))

    pref.set('tasks')
    const secondFlush = pref.flushPendingAsync()
    expect(secondFlush).toBe(firstFlush)
    gate.blockRename = false
    gate.waiters.splice(0).forEach((resolve) => resolve())
    await Promise.all([firstFlush, secondFlush])

    expect(JSON.parse(readFileSync(viewFile(), 'utf-8')).activeView).toBe('tasks')
    expect(gate.renameCalls).toBe(2)
  })

it('keeps an unabortable shared drain alive when an attached signal aborts', async () => {
    const { ActiveViewPreference } = await import('./active-view-preference')
    const pref = new ActiveViewPreference(join(dir, 'orca-data.json'), 'terminal')
    const controller = new AbortController()

    gate.blockRename = true
    pref.set('activity')
    const flush = pref.flushPendingAsync()
    await vi.waitFor(() => expect(gate.renameCalls).toBeGreaterThan(0))
    expect(pref.flushPendingAsync(controller.signal)).toBe(flush)

    pref.set('tasks')
    controller.abort()
    gate.blockRename = false
    gate.waiters.splice(0).forEach((resolve) => resolve())
    await expect(flush).resolves.toBeUndefined()
    expect(JSON.parse(readFileSync(viewFile(), 'utf-8')).activeView).toBe('tasks')
    expect(gate.renameCalls).toBe(2)
  })

it('stops an abortable-only drain after its signal aborts', async () => {
    const { ActiveViewPreference } = await import('./active-view-preference')
    const pref = new ActiveViewPreference(join(dir, 'orca-data.json'), 'terminal')
    const controller = new AbortController()

    gate.blockRename = true
    pref.set('activity')
    const flush = pref.flushPendingAsync(controller.signal)
    await vi.waitFor(() => expect(gate.renameCalls).toBeGreaterThan(0))

    controller.abort()
    gate.blockRename = false
    gate.waiters.splice(0).forEach((resolve) => resolve())
    await expect(flush).rejects.toThrow('Active-view flush aborted')
    expect(gate.renameCalls).toBe(1)
  })

it('migrates the legacy durable-state value into the profile sidecar', async () => {
    vi.useFakeTimers()
    const preference = new ActiveViewPreference(dataFile, 'tasks')

    expect(preference.get()).toBe('tasks')
    expect(existsSync(getActiveViewPreferenceFile(dataFile))).toBe(false)

    // The renderer reasserts its hydrated value once persistence is ready.
    expect(preference.set('tasks')).toBe(false)
    vi.advanceTimersByTime(100)
    await preference.waitForPendingWrite()

    expect(JSON.parse(readFileSync(getActiveViewPreferenceFile(dataFile), 'utf-8'))).toEqual({
      activeView: 'tasks'
    })
  })

it('coalesces rapid switches into one tiny preference write', async () => {
    vi.useFakeTimers()
    const preference = new ActiveViewPreference(dataFile, 'terminal')

    preference.set('settings')
    vi.advanceTimersByTime(50)
    preference.set('automations')
    vi.advanceTimersByTime(50)
    expect(existsSync(getActiveViewPreferenceFile(dataFile))).toBe(false)

    vi.advanceTimersByTime(50)
    await preference.waitForPendingWrite()

    expect(JSON.parse(readFileSync(getActiveViewPreferenceFile(dataFile), 'utf-8'))).toEqual({
      activeView: 'automations'
    })
  })

it('flushes synchronously for an immediate graceful exit', () => {
