named_functions.source:
function workingStatus(): AgentAwakeStatus {
  return {
    paneKey: 'pane-1',
    state: 'working',
    receivedAt: 1_000,
    observedInCurrentRuntime: true
  }
}

function createBlocker() {
  const startedIds = new Set<number>()
  let nextId = 1
  return {
    start: vi.fn(() => {
      const id = nextId++
      startedIds.add(id)
      return id
    }),
    stop: vi.fn((id: number) => {
      startedIds.delete(id)
    }),
    isStarted: vi.fn((id: number) => startedIds.has(id))
  }
}

function createPlatformAssertion() {
  return {
    start: vi.fn(),
    stop: vi.fn(),
    dispose: vi.fn()
  }
}

function createService(
  blocker = createBlocker(),
  macosAssertion = createPlatformAssertion(),
  linuxAssertion = createPlatformAssertion(),
  platform: NodeJS.Platform = 'linux'
): AgentAwakeService {
  return new AgentAwakeService({
    blocker,
    linuxAssertion,
    macosAssertion,
    now: () => 1_000,
    platform,
    powerMonitor: null,
    logger: {
      debug: vi.fn(),
      warn: vi.fn()
    }
  })
}

