    service.setStatuses([])
    service.setStatuses([])

    expect(blocker.stop).toHaveBeenCalledTimes(2)
    expect(blocker.stop).toHaveBeenCalledWith(1)
  })

it('disposes by clearing timers and stopping an active blocker once', () => {
