(label: string) => ({
  label,
  exitCode: 1,
  stdout: '',
  stderr: `${label} failed`
})

export function loadCapture(name: string): CapturedRecord[] {
  return readFileSync(
    join(__dirname, '..', '..', 'shared', '__fixtures__', `${name}.jsonl`),
    'utf8'
  )
    .trim()
    .split('\n')
    .map((line) => {
      // JSON.parse returns any; the kind check below is what proves the record shape.
      const parsed: CapturedRecord = JSON.parse(line)
      if (parsed.kind !== 'hook' && parsed.kind !== 'cancel' && parsed.kind !== 'kill') {
        throw new Error(`Unknown capture record: ${line}`)
      }
      return parsed
    })
}

export function hookAt(records: CapturedRecord[], index: number): CapturedHook {
  const hook = records.find((record) => record.kind === 'hook' && record.index === index)
  if (hook?.kind !== 'hook') {
    throw new Error(`Captured hook ${index} not found`)
  }
  return hook
}

export function cancelLabelled(records: CapturedRecord[], label: string): CapturedCancel {
  const cancel = records.find((record) => record.kind === 'cancel' && record.label === label)
  if (cancel?.kind !== 'cancel') {
    throw new Error(`Captured cancel ${label} not found`)
  }
  return cancel
}

export function hookSupersedesCancel(records: CapturedRecord[], cancel: CapturedCancel): boolean {
  return records.some(
    (record) =>
      record.kind === 'hook' &&
      record.t > cancel.t &&
      (record.t - cancel.t) * 1000 < AGENT_INTERRUPT_SETTLE_MS
  )
}

export function loadClaudeInterruptCapture(name: string) {
  const base = join(__dirname, '../runtime/__fixtures__', `claude-interrupt-${name}`)
  const transcript = readFileSync(`${base}.txt`, 'utf8')
  const events = z.array(captureEvent).parse(JSON.parse(readFileSync(`${base}.input.json`, 'utf8')))
  const titles = extractAllOscTitles(transcript)
  const recordedTitles = events.flatMap((event) => (event.kind === 'title' ? [event.title] : []))
  if (JSON.stringify(titles) !== JSON.stringify(recordedTitles)) {
    throw new Error('Capture timeline must match the raw PTY title frames in byte order')
  }
  let offset = 0
  return events.map((event) => {
    if (event.kind === 'input') {
      return event
    }
    const candidates = ['0', '2'].flatMap((opcode) =>
      ['\x07', '\x1b\\'].map((end) => `\x1b]${opcode};${event.title}${end}`)
    )
    const frame = candidates.find((candidate) => transcript.includes(candidate, offset))
    if (!frame) {
      throw new Error('Captured OSC title frame missing from transcript')
    }
    const end = transcript.indexOf(frame, offset) + frame.length
    const chunk = transcript.slice(offset, end)
    offset = end
    return { ...event, chunk }
  })
}

